import { useEffect, useRef, useState } from 'react'
import type { Session } from '@supabase/supabase-js'
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, BarChart3, Bell, BookOpen, Check, CheckCircle2, ChevronDown, CircleHelp, Code2, Columns3, Copy, CreditCard, Database, Download, FileArchive, FileJson, FileSpreadsheet, FileText, Files, Filter, FlaskConical, GitBranch, KeyRound, LayoutDashboard, LockKeyhole, Menu, MoreHorizontal, PanelLeftClose, Play, Plus, RefreshCw, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Table2, UploadCloud, WandSparkles, X } from 'lucide-react'
import { supabase } from './lib/supabase'

type Column = {name:string;type:string;key:string;pii:boolean;privacy:string;distribution:string;nullable:boolean}
type Config = {name:string;kind:string;domain:string;rows:number;seed:number;locale:string;currency:string;null_rate:number;null_field?:string|null;outlier_rate:number;duplicate_rate:number;scenario:string;columns:Column[];sample:Record<string,unknown>[];rules:string[]}
type TableData = {count:number;preview:Record<string,unknown>[];columns:string[]}
type Quality = {score:number;dimensions:Record<string,number|null>;comparison?:{field:string;measure:string;sample:number;synthetic:number;similarity:number}[];checks:{name:string;passed:boolean;detail:string}[];counts:{rows:number;missing:number;outliers:number;duplicates:number}}
type Result = {id:string;name:string;kind:string;version:number;tables:Record<string,TableData>;quality:Quality;privacy:{fields:{field:string;treatment:string;covered:boolean}[];coverage:number;blocked:boolean;risk:string};flags?:Record<string,number[]>;config?:Config}
type DatasetSummary = {id:string;name:string;kind:string;created_at:string;version:number;score:number;rows:number}
type Billing = {balance:number;free_plan_credits:number;credits_per_thousand_rows:number;checkout_ready:boolean;plans:{id:string;name:string;price_pkr:number;credits:number}[]}
type VersionSummary = {version:number;config:Config;score:number;created_at:string}
type Screen = 'Dashboard'|'Create Dataset'|'Schema Analysis'|'Configure Dataset'|'Generation'|'Dataset Preview'|'DataLens'|'Relationships'|'Scenarios'|'Documents'|'Export Center'|'Datasets'|'Templates'|'Usage & Settings'|'API Playground'|'Admin Panel'|'Help'

const API='/api'
const defaultColumns:Column[]=[
  {name:'customer_id',type:'id',key:'PK',pii:false,privacy:'synthetic',distribution:'unique',nullable:false},
  {name:'full_name',type:'name',key:'',pii:true,privacy:'synthetic',distribution:'semantic',nullable:false},
  {name:'email',type:'email',key:'',pii:true,privacy:'synthetic',distribution:'unique',nullable:true},
  {name:'country',type:'category',key:'',pii:false,privacy:'synthetic',distribution:'categorical',nullable:false},
  {name:'balance',type:'decimal',key:'',pii:false,privacy:'synthetic',distribution:'log-normal',nullable:false},
  {name:'signup_date',type:'date',key:'',pii:false,privacy:'synthetic',distribution:'uniform',nullable:false},
]
const initialConfig:Config={name:'Customer dataset',kind:'tabular',domain:'ecommerce',rows:10000,seed:42,locale:'en_PK',currency:'PKR',null_rate:0.03,null_field:null,outlier_rate:0.01,duplicate_rate:0.01,scenario:'Normal',columns:defaultColumns,sample:[],rules:[]}
const navGroups:{title:string;items:{label:Screen;icon:typeof LayoutDashboard}[]}[]=[
  {title:'WORKSPACE',items:[{label:'Dashboard',icon:LayoutDashboard},{label:'Create Dataset',icon:Plus},{label:'Datasets',icon:Database},{label:'Templates',icon:Files},{label:'Scenarios',icon:FlaskConical}]},
    {title:'ADMINISTRATION',items:[{label:'Admin Panel',icon:ShieldCheck}]},
  {title:'INSIGHTS',items:[{label:'DataLens',icon:BarChart3},{label:'Export Center',icon:ArrowDownToLine},{label:'Usage & Settings',icon:Activity}]},
  {title:'DEVELOPER',items:[{label:'API Playground',icon:Code2},{label:'Help',icon:CircleHelp}]},
]
const scenarioData=[
  {name:'Normal',tag:'BASELINE',description:'Balanced, production-like records with light natural variation.',icon:Activity,values:[.03,.01,.01]},
  {name:'Missing Data',tag:'COMPLETENESS',description:'Test null handling, required fields and incomplete profiles.',icon:Columns3,values:[.12,.01,.01]},
  {name:'Outliers',tag:'DISTRIBUTION',description:'Push numeric ranges and long-tail behavior.',icon:BarChart3,values:[.03,.08,.01]},
  {name:'Duplicates',tag:'UNIQUENESS',description:'Challenge deduplication and idempotency rules.',icon:Files,values:[.03,.01,.08]},
  {name:'High Volume',tag:'SCALE',description:'Run a 100,000 row throughput check.',icon:Database,values:[.03,.01,.01]},
  {name:'Rare Cases',tag:'COVERAGE',description:'Surface uncommon category and boundary combinations.',icon:Sparkles,values:[.04,.04,.01]},
  {name:'Stress Testing',tag:'LOAD',description:'Combine volume and imperfect inputs.',icon:Activity,values:[.08,.05,.04]},
  {name:'Failure',tag:'RECOVERY',description:'Exercise missing and repeated record handling.',icon:ShieldCheck,values:[.15,.04,.06]},
  {name:'Fraud',tag:'PATTERNS',description:'Create elevated amounts and unusual transaction cases.',icon:LockKeyhole,values:[.02,.12,.02]},
]
const relationalSchemas:Record<string,string[][]>={
  ecommerce:[['customers','customer_id PK','full_name','email'],['products','product_id PK','name','price'],['orders','order_id PK','customer_id FK','total'],['order_items','item_id PK','order_id FK','product_id FK','line_total'],['payments','payment_id PK','order_id FK','amount']],
  banking:[['customers','customer_id PK','full_name','email'],['accounts','account_id PK','customer_id FK','opening_balance','balance'],['transactions','transaction_id PK','account_id FK','debit','credit','balance']],
  hospital:[['patients','patient_id PK','full_name','email'],['doctors','doctor_id PK','full_name','specialty'],['appointments','appointment_id PK','patient_id FK','doctor_id FK','appointment_date'],['records','record_id PK','appointment_id FK','diagnosis']],
  university:[['students','student_id PK','full_name','email'],['courses','course_id PK','title','credits'],['enrollments','enrollment_id PK','student_id FK','course_id FK'],['results','result_id PK','enrollment_id FK','score']],
  inventory:[['suppliers','supplier_id PK','name','email'],['products','product_id PK','supplier_id FK','name','price'],['warehouses','warehouse_id PK','name','region'],['stock','stock_id PK','product_id FK','warehouse_id FK','quantity']],
  hr:[['departments','department_id PK','name'],['employees','employee_id PK','department_id FK','full_name','email'],['salaries','salary_id PK','employee_id FK','amount'],['attendance','attendance_id PK','employee_id FK','status']],
  hotel:[['guests','guest_id PK','full_name','email'],['rooms','room_id PK','number','rate'],['bookings','booking_id PK','guest_id FK','room_id FK','total'],['payments','payment_id PK','booking_id FK','amount']],
  library:[['members','member_id PK','full_name','email'],['books','book_id PK','title','author'],['loans','loan_id PK','member_id FK','book_id FK','loan_date'],['returns','return_id PK','loan_id FK','return_date']],
}
const relationEdges:Record<string,[string,string,string][]>={
  ecommerce:[['customers','orders','customer_id'],['orders','order_items','order_id'],['products','order_items','product_id'],['orders','payments','order_id']],
  banking:[['customers','accounts','customer_id'],['accounts','transactions','account_id']],
  hospital:[['patients','appointments','patient_id'],['doctors','appointments','doctor_id'],['appointments','records','appointment_id']],
  university:[['students','enrollments','student_id'],['courses','enrollments','course_id'],['enrollments','results','enrollment_id']],
  inventory:[['suppliers','products','supplier_id'],['products','stock','product_id'],['warehouses','stock','warehouse_id']],
  hr:[['departments','employees','department_id'],['employees','salaries','employee_id'],['employees','attendance','employee_id']],
  hotel:[['guests','bookings','guest_id'],['rooms','bookings','room_id'],['bookings','payments','booking_id']],
  library:[['members','loans','member_id'],['books','loans','book_id'],['loans','returns','loan_id']],
}
const formatNumber=(n:number)=>new Intl.NumberFormat('en-US').format(n)
const titleCase=(s:string)=>s==='hr'?'HR':s.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())
const numberValue=(v:unknown)=>typeof v==='number'?new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(v):String(v??'')
async function apiFetch(input:RequestInfo|URL,init?:RequestInit):Promise<Response>{const headers=new Headers(init?.headers);const session=supabase?(await supabase.auth.getSession()).data.session:null;if(session)headers.set('Authorization',`Bearer ${session.access_token}`);return fetch(input,{...init,headers})}
async function request<T>(path:string, init?:RequestInit):Promise<T>{const response=await apiFetch(API+path,init);if(!response.ok){let error='The request failed';try{const body=await response.json();error=body.detail||error}catch{}throw new Error(error)}return response.json()}

function Brand(){return <div className="brand"><div className="brand-mark"><span/><span/><span/><span/></div><div><strong>HYPERSION</strong><small>GEN PLATFORM</small></div></div>}
function Pill({children,tone='neutral'}:{children:React.ReactNode;tone?:string}){return <span className={'pill '+tone}>{children}</span>}
function SectionHeading({eyebrow,title,description,action}:{eyebrow?:string;title:string;description?:string;action?:React.ReactNode}){return <div className="section-heading"><div>{eyebrow&&<div className="eyebrow">{eyebrow}</div>}<h2>{title}</h2>{description&&<p>{description}</p>}</div>{action}</div>}
function Empty({icon:Icon=Database,title,detail,action}:{icon?:typeof Database;title:string;detail:string;action?:React.ReactNode}){return <div className="empty"><div className="empty-icon"><Icon size={26}/></div><h3>{title}</h3><p>{detail}</p>{action}</div>}
function ProgressBar({value}:{value:number}){return <div className="progress-track"><div style={{width:`${Math.max(0,Math.min(100,value))}%`}}/></div>}
function Metric({label,value,detail,icon:Icon}:{label:string;value:string|number;detail?:string;icon:typeof Database}){return <div className="metric"><div className="metric-top"><span>{label}</span><Icon size={18}/></div><strong>{value}</strong><small>{detail}</small></div>}

export default function App(){
  const [screen,setScreen]=useState<Screen>('Dashboard')
  const [config,setConfig]=useState<Config>(initialConfig)
  const [result,setResult]=useState<Result|null>(null)
  const [datasets,setDatasets]=useState<DatasetSummary[]>([])
  const [billing,setBilling]=useState<Billing|null>(null)
  const [versions,setVersions]=useState<VersionSummary[]>([])
  const [versionTarget,setVersionTarget]=useState<string|null>(null)
  const [prompt,setPrompt]=useState('Generate 10,000 e-commerce customers with realistic names, emails, locations and 5% missing phone numbers.')
  const [source,setSource]=useState('Describe with AI')
  const [confidence,setConfidence]=useState<number|null>(null)
  const [explanation,setExplanation]=useState('')
  const [busy,setBusy]=useState(false)
  const [progress,setProgress]=useState(0)
  const [toast,setToast]=useState('')
  const [authSession,setAuthSession]=useState<Session|null>(null)
  const [authLoading,setAuthLoading]=useState(true)
  const [authError,setAuthError]=useState('')
  const [authNotice,setAuthNotice]=useState('')
  const [authBusy,setAuthBusy]=useState(false)
  const [theme,setTheme]=useState<'dark'|'light'>('dark')
  const [sidebarOpen,setSidebarOpen]=useState(false)
  const [activeTable,setActiveTable]=useState('')
  const [previewTab,setPreviewTab]=useState('Preview')
  const [search,setSearch]=useState('')
  const [page,setPage]=useState(0)
  const [rows,setRows]=useState<Record<string,unknown>[]>([])
  const [rowFlags,setRowFlags]=useState<string[][]>([])
  const [rowTotal,setRowTotal]=useState(0)
  const [documentKind,setDocumentKind]=useState<'invoice'|'statement'>('invoice')
  const [document,setDocument]=useState<Record<string,any>|null>(null)
  const [apiResponse,setApiResponse]=useState('')
  const [apiEndpoint,setApiEndpoint]=useState('/api/health')
  const [apiMethod,setApiMethod]=useState<'GET'|'POST'>('GET')
  const [apiBody,setApiBody]=useState(JSON.stringify(initialConfig,null,2))
  const [apiStatus,setApiStatus]=useState<number|null>(null)
  const [apiBusy,setApiBusy]=useState(false)
  const [adminHealth,setAdminHealth]=useState<boolean|null>(null)
  const [openRouterStatus,setOpenRouterStatus]=useState<{configured:boolean;model:string}|null>(null)
  const [databaseStatus,setDatabaseStatus]=useState<{configured:boolean;provider:string}|null>(null)
  const fileRef=useRef<HTMLInputElement>(null)

  useEffect(()=>{if(!supabase){setAuthLoading(false);return}let active=true;const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,session)=>{setAuthSession(session);setAuthLoading(false)});supabase.auth.getSession().then(({data,error})=>{if(active){setAuthSession(data.session);setAuthLoading(false);if(error)setAuthError(error.message)}});return()=>{active=false;subscription.unsubscribe()}},[])
  const notify=(message:string)=>{setToast(message);window.setTimeout(()=>setToast(''),4500)}
  async function signInWithEmail(email:string){if(!supabase)return;setAuthBusy(true);setAuthError('');setAuthNotice('');try{const {error}=await supabase.auth.signInWithOtp({email,options:{emailRedirectTo:window.location.origin}});if(error)setAuthError(error.message);else setAuthNotice('Check your email for a sign-in link. Open it on this device to continue.')}catch{setAuthError('Could not send a sign-in link. Please try again.')}finally{setAuthBusy(false)}}
  async function signOut(){if(!supabase)return;const {error}=await supabase.auth.signOut();if(error)notify(error.message)}
  const go=(next:Screen)=>{if(next==='Create Dataset')setVersionTarget(null);setScreen(next);setSidebarOpen(false);window.scrollTo(0,0)}
  const refresh=()=>request<DatasetSummary[]>('/datasets').then(setDatasets).catch(()=>{})
  const refreshBilling=()=>request<Billing>('/billing').then(setBilling).catch(()=>{})
  useEffect(()=>{if(authSession){refresh();refreshBilling()}},[authSession])
  useEffect(()=>{if(result)request<VersionSummary[]>(`/datasets/${result.id}/versions`).then(setVersions).catch(()=>{})},[result?.id,result?.version])
  useEffect(()=>{if(!result||!activeTable)return;const timer=window.setTimeout(()=>{request<{total:number;rows:Record<string,unknown>[];flags:string[][]}>(`/datasets/${result.id}/rows?table=${encodeURIComponent(activeTable)}&offset=${page*25}&limit=25&search=${encodeURIComponent(search)}&version=${result.version}`).then(data=>{setRows(data.rows);setRowFlags(data.flags);setRowTotal(data.total)}).catch(e=>notify(e.message))},250);return()=>clearTimeout(timer)},[result?.id,result?.version,activeTable,page,search])
  useEffect(()=>{if(!result||screen!=='Documents')return;request<Record<string,any>>(`/datasets/${result.id}/document/${documentKind}?version=${result.version}`).then(setDocument).catch(()=>setDocument(null))},[result?.id,result?.version,documentKind,screen])
  useEffect(()=>{if(screen!=='Admin Panel'&&screen!=='Usage & Settings')return;let active=true;Promise.all([request<{status:string}>('/health'),request<{openrouter:{configured:boolean;model:string};database:{configured:boolean;provider:string}}>('/integrations')]).then(([health,integration])=>{if(active){setAdminHealth(health.status==='ok');setOpenRouterStatus(integration.openrouter);setDatabaseStatus(integration.database)}}).catch(()=>{if(active){setAdminHealth(false);setOpenRouterStatus(null);setDatabaseStatus(null)}});return()=>{active=false}},[screen])
  useEffect(()=>{if(result?.config?.domain==='banking')setDocumentKind('statement');else if(result?.kind==='relational')setDocumentKind('invoice')},[result?.id,result?.version])

  async function analyzePrompt(){setBusy(true);try{const analysis=await request<any>('/analyze/prompt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt})});setConfig(prev=>({...prev,name:analysis.name||prev.name,kind:analysis.kind||'tabular',domain:analysis.domain||'ecommerce',rows:analysis.rows||prev.rows,null_rate:analysis.null_rate??prev.null_rate,null_field:analysis.null_field??null,columns:analysis.columns||prev.columns,sample:[]}));setConfidence(analysis.confidence||0.75);setSource(analysis.source||'Describe with AI');setExplanation(analysis.explanation||'');go('Schema Analysis')}catch(e){notify((e as Error).message)}finally{setBusy(false)}}
  async function upload(file:File){setBusy(true);try{const form=new FormData();form.append('file',file);const analysis=await request<any>('/analyze/csv',{method:'POST',body:form});setConfig(prev=>({...prev,name:file.name.replace(/\.csv$/i,'')+' synthetic',kind:'tabular',columns:analysis.columns,sample:analysis.sample}));setConfidence(analysis.confidence);setSource('CSV sample');setExplanation(analysis.explanation);go('Schema Analysis')}catch(e){notify((e as Error).message)}finally{setBusy(false)}}
  async function generate(){setBusy(true);setProgress(8);go('Generation');const timer=window.setInterval(()=>setProgress(p=>Math.min(p+Math.max(1,(90-p)/9),90)),320);try{const path=versionTarget?`/datasets/${versionTarget}/versions`:'/generate';const data=await request<Result>(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(config)});setResult({...data,config});setActiveTable(Object.keys(data.tables)[0]);setPage(0);setSearch('');setProgress(100);refresh();refreshBilling();notify(versionTarget?`Version ${data.version} saved`:'Generation complete — your dataset is ready');setVersionTarget(null)}catch(e){notify((e as Error).message);go('Configure Dataset')}finally{window.clearInterval(timer);setBusy(false)}}
  async function sendApiRequest(){setApiBusy(true);setApiStatus(null);try{const body=apiMethod==='POST'?JSON.parse(apiBody):undefined;const response=await apiFetch(apiEndpoint,{method:apiMethod,headers:apiMethod==='POST'?{'Content-Type':'application/json'}:undefined,body:body===undefined?undefined:JSON.stringify(body)});setApiStatus(response.status);const disposition=response.headers.get('content-disposition');if(disposition){const blob=await response.blob();const object=URL.createObjectURL(blob);const link=window.document.createElement('a');link.href=object;link.download=(disposition.match(/filename="([^"]+)"/)||[])[1]||'hypersion-export';link.click();URL.revokeObjectURL(object);setApiResponse(JSON.stringify({status:response.status,message:`Downloaded ${link.download}`,content_type:response.headers.get('content-type')},null,2));return}const text=await response.text();try{setApiResponse(JSON.stringify(JSON.parse(text),null,2))}catch{setApiResponse(text||'No response body')}}catch(e){setApiResponse(JSON.stringify({error:(e as Error).message},null,2))}finally{setApiBusy(false)}}
  function downloadApiResponse(){if(!apiResponse)return;const object=URL.createObjectURL(new Blob([apiResponse],{type:'application/json'}));const link=window.document.createElement('a');link.href=object;link.download='api-response.json';link.click();URL.revokeObjectURL(object)}
  function download(fmt:string){if(!result)return;const url=`${API}/datasets/${result.id}/export/${fmt}?version=${result.version}`;apiFetch(url).then(async response=>{if(!response.ok){const data=await response.json();throw new Error(data.detail||'Export failed')}const blob=await response.blob();const object=URL.createObjectURL(blob);const link=window.document.createElement('a');link.href=object;link.download=(response.headers.get('content-disposition')?.match(/filename="([^"]+)"/)||[])[1]||`hypersion.${fmt}`;link.click();URL.revokeObjectURL(object);notify(`${fmt.toUpperCase()} download started`)}).catch(e=>notify(e.message))}
  function downloadDocument(fmt:string){if(!result)return;apiFetch(`${API}/datasets/${result.id}/document/${documentKind}/export/${fmt}?version=${result.version}`).then(async response=>{if(!response.ok){const data=await response.json();throw new Error(data.detail||'Document export failed')}const blob=await response.blob();const object=URL.createObjectURL(blob);const link=window.document.createElement('a');link.href=object;link.download=(response.headers.get('content-disposition')?.match(/filename="([^"]+)"/)||[])[1]||`${documentKind}.${fmt}`;link.click();URL.revokeObjectURL(object);notify(`${documentKind} ${fmt.toUpperCase()} downloaded`)}).catch(e=>notify(e.message))}
  async function openDataset(id:string,version?:number){try{const data=await request<Result>(`/datasets/${id}${version?`?version=${version}`:''}`);setResult({...data,config:{...initialConfig,...data.config}});setConfig({...initialConfig,...data.config});setVersionTarget(null);setActiveTable(Object.keys(data.tables)[0]);setPage(0);setSearch('');go('Dataset Preview')}catch(e){notify((e as Error).message)}}
  function applyScenario(name:string){const item=scenarioData.find(s=>s.name===name)!;setConfig(prev=>({...prev,scenario:name,rows:name==='High Volume'||name==='Stress Testing'?100000:prev.rows,null_rate:item.values[0],outlier_rate:item.values[1],duplicate_rate:item.values[2]}));notify(`${name} scenario applied`);go('Configure Dataset')}
  function selectTemplate(kind:string){const relational=kind==='relational'||Boolean(relationalSchemas[kind]);const domain=kind==='relational'?'ecommerce':relational?kind:'ecommerce';setConfig(prev=>({...prev,name:relational?`${titleCase(domain)} operations`:`${kind} dataset`,kind:relational?'relational':'tabular',domain,columns:relational?[]:defaultColumns}));setDocumentKind(domain==='banking'?'statement':'invoice');setSource('Template');setConfidence(1);setExplanation(relational?'Review the built-in relationships, then configure generation.':'Template selected. Edit the schema before generating.');go('Schema Analysis')}
  function setColumn(index:number,patch:Partial<Column>){setConfig(prev=>({...prev,columns:prev.columns.map((c,i)=>i===index?{...c,...patch}:c)}))}
  const navActive=(label:Screen)=>label===screen||(label==='Create Dataset'&&['Schema Analysis','Configure Dataset','Generation'].includes(screen))||(label==='Datasets'&&['Dataset Preview','Relationships','Documents'].includes(screen))||(label==='DataLens'&&screen==='DataLens')||(label==='Export Center'&&screen==='Export Center')
  const resultReady=!!result
  if(!authSession)return <AuthScreen configured={!!supabase} loading={authLoading} busy={authBusy} error={authError} notice={authNotice} onSignIn={signInWithEmail}/>
  return <div className={`app ${theme}`}>
    <aside className={'sidebar '+(sidebarOpen?'open':'')}>
      <div className="sidebar-head"><Brand/><button className="icon-button sidebar-collapse" onClick={()=>setSidebarOpen(false)} aria-label="Close menu"><PanelLeftClose size={17}/></button></div>
      <div className="workspace-switch"><div className="workspace-avatar">H</div><div><strong>Hypersion Workspace</strong><span>Personal workspace</span></div><ChevronDown size={15}/></div>
      <nav>{navGroups.map(group=><div className="nav-group" key={group.title}><span className="nav-caption">{group.title}</span>{group.items.map(item=><button key={item.label} className={'nav-item '+(navActive(item.label)?'active':'')} onClick={()=>go(item.label)}><item.icon size={18}/><span>{item.label==='Export Center'?'Exports':item.label==='DataLens'?'Analytics':item.label==='Usage & Settings'?'Usage':item.label==='API Playground'?'API':item.label}</span>{item.label==='Create Dataset'&&<span className="nav-plus">+</span>}</button>)}</div>)}</nav>
      <div className="sidebar-bottom"><div className="plan-card"><div className="plan-icon"><Sparkles size={16}/></div><strong>Build with confidence</strong><p>Generate, validate and export data your team can trust.</p><div className="plan-progress"><span>LOCAL WORKSPACE</span><span>ACTIVE</span></div><ProgressBar value={76}/></div><div className="sidebar-user"><div className="user-avatar">HG</div><div><strong>Workspace Admin</strong><span>Local development</span></div><MoreHorizontal size={17}/></div></div>
    </aside>
    {sidebarOpen&&<div className="mobile-scrim" onClick={()=>setSidebarOpen(false)}/>}
    <div className="main-shell">
      <header className="topbar"><div className="topbar-left"><button className="icon-button mobile-menu" onClick={()=>setSidebarOpen(true)} aria-label="Open menu"><Menu size={20}/></button><span>Workspace</span><span className="crumb-divider">/</span><strong>{screen}</strong></div><div className="topbar-right"><span className="system-status"><span/> All systems operational</span><span className="topbar-divider"/><button className="icon-button" onClick={()=>go('Help')} aria-label="Help"><CircleHelp size={18}/></button><button className="icon-button" onClick={()=>notify('You are all caught up')} aria-label="Notifications"><Bell size={18}/></button><button className="button secondary auth-sign-out" onClick={signOut}>Sign out</button></div></header>
      <main className="content">
        {screen==='DataLens'&&result&&<ValidationExplanation datasetId={result.id} version={result.version}/>}
        {screen==='Admin Panel'&&<>
          <SectionHeading eyebrow="ADMINISTRATION / LOCAL WORKSPACE" title="Admin panel" description="Monitor generation activity, workspace data and service configuration." action={<button className="button primary" onClick={()=>go('Create Dataset')}><Plus size={16}/> Create dataset</button>}/>
          <div className="metrics-grid">
            <Metric label="Datasets" value={datasets.length} detail="Saved workspace datasets" icon={Database}/>
            <Metric label="Synthetic records" value={formatNumber(datasets.reduce((total,dataset)=>total+dataset.rows,0))} detail="Across current dataset versions" icon={Table2}/>
            <Metric label="Average quality" value={datasets.length?`${Math.round(datasets.reduce((total,dataset)=>total+dataset.score,0)/datasets.length)}/100`:'—'} detail="Computed validation scores" icon={ShieldCheck}/>
            <Metric label="API health" value={adminHealth===null?'Checking':adminHealth?'Online':'Offline'} detail="FastAPI service status" icon={Activity}/>
          </div>
          <div className="info-strip warning"><LockKeyhole size={19}/><div><strong>Private datasets</strong><span>Supabase sign-in protects the API. Each user can access only their own datasets.</span></div></div>
          <div className="dashboard-grid">
            <div className="panel"><div className="panel-head"><div><h3>Recent datasets</h3><p>Current saved versions</p></div><button className="text-button" onClick={()=>go('Datasets')}>View datasets <ArrowRight size={15}/></button></div>
              {datasets.length?<div className="dataset-list">{datasets.slice(0,6).map(dataset=><button className="dataset-row" key={dataset.id} onClick={()=>openDataset(dataset.id)}><div className="dataset-icon"><Database size={18}/></div><div className="dataset-main"><strong>{dataset.name}</strong><span>{titleCase(dataset.kind)} · {formatNumber(dataset.rows)} records</span></div><Pill tone={dataset.score>=90?'good':'warn'}>{dataset.score}/100</Pill><span>v{dataset.version}</span></button>)}</div>:<Empty title="No saved datasets" detail="Generated datasets will appear here for workspace review." action={<button className="button secondary" onClick={()=>go('Create Dataset')}><Plus size={15}/> Create dataset</button>}/>}
            </div>
            <div className="panel"><div className="panel-head"><div><h3>Service configuration</h3><p>Backend integration status</p></div><Settings2 size={19}/></div>
              <div className="summary-list"><div><span>API service</span><Pill tone={adminHealth?'good':adminHealth===false?'warn':'neutral'}>{adminHealth===null?'CHECKING':adminHealth?'ONLINE':'OFFLINE'}</Pill></div><div><span>Database</span><Pill tone={databaseStatus?.configured?'good':'neutral'}>{databaseStatus?.provider==='supabase-postgres'?'SUPABASE POSTGRES':databaseStatus?.provider==='postgres'?'POSTGRES':databaseStatus?.provider==='sqlite'?'SQLITE LOCAL':'UNAVAILABLE'}</Pill></div><div><span>Browser client</span><Pill tone={supabase?'good':'neutral'}>{supabase?'CONFIGURED':'NOT CONFIGURED'}</Pill></div><div><span>OpenRouter</span><Pill tone={openRouterStatus?.configured?'good':'warn'}>{openRouterStatus?.configured?'CONFIGURED':'NOT CONFIGURED'}</Pill></div><div><span>Default model</span><strong>{openRouterStatus?.model||'Unavailable'}</strong></div><div><span>Workspace role</span><strong>Local admin label only</strong></div></div>
              <div className="api-hint"><KeyRound size={16}/><span>Provider credentials remain on the backend. Role enforcement requires authentication to be configured.</span></div>
            </div>
          </div>
        </>}
        {screen==='Dashboard'&&<><div className="dashboard-hero"><div className="hero-copy"><div className="hero-label"><span/> SYNTHETIC DATA PLATFORM <ArrowRight size={13}/></div><h1>Data that feels real.<br/><em>Without the risk.</em></h1><p>Generate realistic, validated test data from a schema, sample, or simple description. Ready for the systems you build next.</p><button className="button primary hero-button" onClick={()=>go('Create Dataset')}><Plus size={18}/> Create Dataset <ArrowRight size={17}/></button></div><div className="hero-art" aria-hidden="true"><div className="art-grid"/><div className="art-window"><div className="art-title"><span className="art-dot"/> generation_run_042 <span className="art-live">LIVE</span></div><div className="art-line"><span className="mono cyan">01</span><span>schema.analyze(<span className="cyan">"customers"</span>)</span></div><div className="art-line"><span className="mono cyan">02</span><span>generate.seed(<span className="gold">42</span>)</span></div><div className="art-line"><span className="mono cyan">03</span><span>validate.integrity()</span></div><div className="art-success"><CheckCircle2 size={15}/> 10,000 records · Quality 94/100</div></div></div></div>
          <div className="pipeline"><div className="pipeline-label">FROM IDEA TO USABLE DATA</div><div className="pipeline-steps">{['Describe / Upload','AI Analysis','Generate','Validate','Privacy','Export'].map((x,i)=><div key={x} className="pipeline-step"><span>{String(i+1).padStart(2,'0')}</span>{x}{i<5&&<ArrowRight size={15}/>}</div>)}</div></div>
          <div className="metrics-grid"><Metric label="Total datasets" value={datasets.length} detail="Across your workspace" icon={Database}/><Metric label="Records generated" value={formatNumber(datasets.reduce((a,d)=>a+d.rows,0))} detail="Synthetic records" icon={Table2}/><Metric label="Average quality" value={datasets.length?`${Math.round(datasets.reduce((a,d)=>a+d.score,0)/datasets.length)}/100`:'—'} detail="Computed validation score" icon={ShieldCheck}/><Metric label="Latest version" value={datasets.length?`v${datasets[0].version}`:'—'} detail="Deterministic & reproducible" icon={GitBranch}/></div>
          <div className="dashboard-grid"><div className="panel"><div className="panel-head"><div><h3>Recent datasets</h3><p>Pick up where you left off</p></div><button className="text-button" onClick={()=>go('Datasets')}>View all <ArrowRight size={16}/></button></div>{datasets.length?<div className="dataset-list">{datasets.slice(0,4).map(d=><button className="dataset-row" key={d.id} onClick={()=>openDataset(d.id)}><div className="dataset-icon"><Database size={19}/></div><div className="dataset-main"><strong>{d.name}</strong><span>{titleCase(d.kind)} · {formatNumber(d.rows)} records</span></div><Pill tone={d.score>=90?'good':'warn'}>{d.score}/100</Pill><ArrowRight size={16}/></button>)}</div>:<Empty title="Your workspace is ready" detail="Create a dataset to see recent activity and quality insights here." action={<button className="button secondary" onClick={()=>go('Create Dataset')}><Plus size={16}/> Create dataset</button>}/>}</div><div className="panel quickstart"><div className="panel-head"><div><h3>Start with a workflow</h3><p>Choose a way to begin</p></div></div><button onClick={()=>go('Create Dataset')}><div className="quick-icon teal"><WandSparkles size={20}/></div><div><strong>Describe with AI</strong><span>Go from intent to editable schema</span></div><ArrowRight size={16}/></button><button onClick={()=>fileRef.current?.click()}><div className="quick-icon blue"><UploadCloud size={20}/></div><div><strong>Analyze a CSV</strong><span>Learn from your sample's structure</span></div><ArrowRight size={16}/></button><button onClick={()=>selectTemplate('relational')}><div className="quick-icon amber"><GitBranch size={20}/></div><div><strong>Relational dataset</strong><span>Connected tables with valid keys</span></div><ArrowRight size={16}/></button></div></div>
        </>}

        {screen==='Create Dataset'&&<><SectionHeading eyebrow="01 / INPUT" title="Create a dataset" description="Start with a sentence, a sample, a schema, or a template. We'll turn it into an editable plan."/><div className="create-layout"><div className="panel copilot-panel"><div className="panel-kicker"><div className="copilot-icon"><Sparkles size={20}/></div><span>AI DATASET COPILOT</span><Pill tone="accent">CONTEXT AWARE</Pill></div><h3>What data do you need?</h3><p>Describe the people, entities, fields or conditions you want to test.</p><textarea value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="e.g. Generate 10,000 e-commerce customers with realistic names and 5% missing phone numbers"/><div className="prompt-footer"><span><Sparkles size={14}/> Schema only — rows are generated deterministically</span><button className="button primary" disabled={busy} onClick={analyzePrompt}>{busy?'Analyzing…':'Analyze request'}<ArrowRight size={17}/></button></div><div className="prompt-examples"><span>TRY AN EXAMPLE</span>{['10,000 e-commerce customers with 5% missing phone numbers','Employee records with salary and joining dates','Financial transactions with unusual amounts'].map(x=><button key={x} onClick={()=>setPrompt('Generate '+x)}>{x}<ArrowRight size={13}/></button>)}</div></div><div className="create-aside"><div className="aside-title">OTHER WAYS TO START</div><button className="entry-card" onClick={()=>fileRef.current?.click()}><div className="entry-icon"><UploadCloud size={20}/></div><div><strong>Upload CSV</strong><span>Infer types and distributions from a sample</span></div><ArrowRight size={17}/></button><button className="entry-card" onClick={()=>{setSource('Manual schema');setConfidence(1);go('Schema Analysis')}}><div className="entry-icon"><Columns3 size={20}/></div><div><strong>Define Schema</strong><span>Build and edit fields yourself</span></div><ArrowRight size={17}/></button><button className="entry-card" onClick={()=>go('Templates')}><div className="entry-icon"><Files size={20}/></div><div><strong>Use Template</strong><span>Start with a proven data structure</span></div><ArrowRight size={17}/></button><div className="privacy-note"><ShieldCheck size={20}/><div><strong>Privacy by design</strong><p>Generated values are synthetic. Upload only non-sensitive samples; sample rows are stored locally with dataset versions.</p></div></div></div></div></>}

        {screen==='Schema Analysis'&&<><FlowHeader step={2} title="Review your schema" subtitle="The detected structure is a proposal. Edit every field before generating."/><div className="analysis-summary"><div><Sparkles size={19}/><strong>{source}</strong><span>{explanation||'Review the inferred fields and data types.'}</span></div><Pill tone="accent">{confidence?Math.round(confidence*100):100}% confidence</Pill></div>{config.kind==='relational'?<RelationalSchema domain={config.domain}/>:<div className="panel schema-panel"><div className="panel-head"><div><h3>Detected columns</h3><p>{config.columns.length} fields · editable schema</p></div><button className="button subtle" onClick={()=>setConfig(prev=>({...prev,columns:[...prev.columns,{name:'new_field',type:'text',key:'',pii:false,privacy:'synthetic',distribution:'auto',nullable:false}]}))}><Plus size={15}/> Add field</button></div><div className="table-scroll"><table className="data-table schema-table"><thead><tr><th>FIELD NAME</th><th>TYPE</th><th>KEY</th><th>DISTRIBUTION</th><th>PII</th><th>PRIVACY RULE</th><th></th></tr></thead><tbody>{config.columns.map((col,i)=><tr key={i}><td><input value={col.name} onChange={e=>setColumn(i,{name:e.target.value})}/></td><td><select value={col.type} onChange={e=>setColumn(i,{type:e.target.value})}>{['id','name','email','phone','text','category','date','integer','decimal'].map(t=><option key={t}>{t}</option>)}</select></td><td><select value={col.key} onChange={e=>setColumn(i,{key:e.target.value})}><option value="">—</option><option>PK</option><option>FK</option></select></td><td><span className="distribution">{col.distribution}</span></td><td><label className="checkbox-inline"><input type="checkbox" checked={col.pii} onChange={e=>setColumn(i,{pii:e.target.checked})}/>{col.pii?'Sensitive':'No'}</label></td><td><select value={col.privacy} onChange={e=>setColumn(i,{privacy:e.target.value})}><option value="synthetic">Synthetic</option><option value="mask">Mask</option><option value="hash">Hash</option><option value="noise">Noise</option><option value="none">Untreated</option></select></td><td><button className="icon-button" onClick={()=>setConfig(prev=>({...prev,columns:prev.columns.filter((_,j)=>j!==i)}))} aria-label="Remove field"><X size={15}/></button></td></tr>)}</tbody></table></div></div>}<div className="info-strip"><ShieldCheck size={18}/><div><strong>Privacy checkpoint</strong><span>Sensitive fields require a treatment before export. Untreated fields will block downloads.</span></div></div><div className="page-actions"><button className="button secondary" onClick={()=>go('Create Dataset')}><ArrowLeft size={16}/> Back</button><button className="button primary" onClick={()=>go('Configure Dataset')}>Configure dataset <ArrowRight size={17}/></button></div></>}

        {screen==='Configure Dataset'&&<><FlowHeader step={3} title="Configure generation" subtitle="Control volume, reproducibility, edge cases and privacy before running the engine."/><ActionBar generate={generate} preview={()=>go('Dataset Preview')} validate={()=>go('DataLens')} download={()=>download('csv')} exportPage={()=>go('Export Center')} ready={resultReady} busy={busy}/><div className="config-grid"><div className="panel config-panel"><div className="panel-head"><div><h3>Core settings</h3><p>Every run saves the full configuration</p></div><SlidersHorizontal size={19}/></div><div className="form-grid"><label>Dataset name<input value={config.name} onChange={e=>setConfig({...config,name:e.target.value})}/></label><label>Engine<select value={config.kind} onChange={e=>setConfig({...config,kind:e.target.value})}><option value="tabular">Tabular</option><option value="relational">Relational</option></select></label>{config.kind==='relational'&&<label>Domain<select value={config.domain} onChange={e=>setConfig({...config,domain:e.target.value})}><option value="ecommerce">E-commerce</option><option value="banking">Banking</option><option value="hospital">Hospital</option><option value="university">University</option><option value="inventory">Inventory</option><option value="hr">Human resources</option><option value="hotel">Hotel</option><option value="library">Library</option></select></label>}<label>Rows<input type="number" min="10" max="100000" value={config.rows} onChange={e=>setConfig({...config,rows:Number(e.target.value)})}/></label><label>Random seed<input type="number" value={config.seed} onChange={e=>setConfig({...config,seed:Number(e.target.value)})}/></label><label>Locale<select value={config.locale} onChange={e=>setConfig({...config,locale:e.target.value})}><option>en_PK</option><option>en_US</option><option>en_GB</option></select></label><label>Currency<select value={config.currency} onChange={e=>setConfig({...config,currency:e.target.value})}><option>PKR</option><option>USD</option><option>GBP</option></select></label></div><div className="config-divider"/><h4>Edge-case composition</h4><p className="muted">Deliberately inject test conditions at exact rates.</p>{config.kind==='tabular'&&<label className="field-label">MISSING-VALUE FIELD<select value={config.null_field||''} onChange={e=>setConfig({...config,null_field:e.target.value||null})}><option value="">Any eligible field</option>{config.columns.filter(c=>c.key!=='PK'&&c.type!=='id').map(c=><option key={c.name} value={c.name}>{c.name}</option>)}</select></label>}<div className="slider-group">{[{key:'null_rate',label:'Missing values',max:30},{key:'outlier_rate',label:'Outliers',max:20},{key:'duplicate_rate',label:'Duplicates',max:20}].map(x=><div className="slider-row" key={x.key}><div><strong>{x.label}</strong><span>{Math.round(Number(config[x.key as keyof Config])*100)}%</span></div><input type="range" min="0" max={x.max} value={Math.round(Number(config[x.key as keyof Config])*100)} onChange={e=>setConfig({...config,[x.key]:Number(e.target.value)/100})}/></div>)}</div><div className="config-divider"/><h4>Business rules</h4><p className="muted">Optional numeric rules, such as <code>age &gt;= 18</code>.</p><input className="full-input" value={config.rules.join(', ')} onChange={e=>setConfig({...config,rules:e.target.value.split(',').map(s=>s.trim()).filter(Boolean)})} placeholder="age >= 18, balance >= 0"/></div><div className="config-side"><div className="panel"><div className="panel-head"><div><h3>Generation summary</h3><p>Ready to run</p></div><Pill tone="good"><Check size={13}/> READY</Pill></div><div className="summary-list"><div><span>Engine</span><strong>{config.kind==='relational'?titleCase(config.domain):titleCase(config.kind)}</strong></div><div><span>Rows</span><strong>{formatNumber(config.rows)}</strong></div><div><span>Fields</span><strong>{config.kind==='relational'?(relationalSchemas[config.domain]?.length||0)+' tables':config.columns.length}</strong></div><div><span>Seed</span><strong className="mono">{config.seed}</strong></div><div><span>Scenario</span><strong>{config.scenario}</strong></div></div><button className="button primary wide" onClick={generate} disabled={busy}><Play size={17}/> Generate dataset</button></div><div className="panel scenario-mini"><div className="panel-head"><div><h3>Test scenario</h3><p>Choose a controlled condition</p></div></div><select value={config.scenario} onChange={e=>applyScenario(e.target.value)}>{scenarioData.map(s=><option key={s.name}>{s.name}</option>)}</select><button className="text-button" onClick={()=>go('Scenarios')}>Explore scenarios <ArrowRight size={15}/></button></div><div className="repro-note"><RefreshCw size={18}/><div><strong>Reproducible by design</strong><p>Same schema, settings and seed produce the same records and ordering.</p></div></div></div></div></>}

        {screen==='Generation'&&<><FlowHeader step={4} title="Generation run" subtitle="Your synthetic dataset is moving through the pipeline."/><ActionBar generate={generate} preview={()=>go('Dataset Preview')} validate={()=>go('DataLens')} download={()=>download('csv')} exportPage={()=>go('Export Center')} ready={resultReady} busy={busy}/>{busy?<div className="panel generation-panel"><div className="generation-orb"><RefreshCw size={32}/></div><h2>Generating your dataset</h2><p>Deterministic engines are creating values from your schema and settings.</p><div className="generation-progress"><div><strong>{Math.round(progress)}%</strong><span>{formatNumber(Math.round(config.rows*progress/100))} of {formatNumber(config.rows)} rows</span></div><ProgressBar value={progress}/></div><div className="job-stages">{['Started','AI analysis','Generating','Validation','Completed'].map((s,i)=><div className={progress>=(i+1)*20?'done':''} key={s}><span>{progress>=(i+1)*20?<Check size={14}/>:i+1}</span>{s}</div>)}</div></div>:result?<><div className="complete-banner"><div className="complete-icon"><Check size={24}/></div><div><div className="eyebrow">RUN COMPLETE</div><h2>Generation complete</h2><p>{formatNumber(result.quality.counts.rows)} rows generated · Seed {config.seed} · Version {result.version}</p></div><div className="complete-score"><span>QUALITY SCORE</span><strong>{result.quality.score}<small>/100</small></strong></div><Pill tone={result.privacy.blocked?'warn':'good'}>Privacy Risk: {result.privacy.risk}</Pill></div><div className="download-actions"><button className="button primary" onClick={()=>go('Dataset Preview')}><Table2 size={16}/> Preview data</button>{['csv','json','txt','zip'].map(fmt=><button key={fmt} className="button secondary" onClick={()=>download(fmt)}><Download size={16}/> {fmt.toUpperCase()}</button>)}</div><div className="metrics-grid"><Metric label="Completeness" value={`${result.quality.dimensions.Completeness}%`} detail="Populated cells" icon={Columns3}/><Metric label="Uniqueness" value={`${result.quality.dimensions.Uniqueness}%`} detail="Controlled duplicates" icon={Files}/><Metric label="Integrity" value={`${result.quality.dimensions['Referential integrity']}%`} detail="Resolved relationships" icon={GitBranch}/><Metric label="Privacy coverage" value={`${result.privacy.coverage}%`} detail="Sensitive fields treated" icon={ShieldCheck}/></div></>:<Empty title="No run yet" detail="Configure a dataset, then start generation." action={<button className="button primary" onClick={()=>go('Configure Dataset')}>Configure dataset</button>}/>}</>}

        {screen==='Datasets'&&<><SectionHeading eyebrow="WORKSPACE / LIBRARY" title="Datasets" description="Every generated run, ready to inspect and export." action={<button className="button primary" onClick={()=>go('Create Dataset')}><Plus size={17}/> Create dataset</button>}/><div className="panel"><div className="panel-head"><div><h3>All datasets</h3><p>{datasets.length} datasets in this workspace</p></div><Database size={19}/></div>{datasets.length?<div className="table-scroll"><table className="data-table"><thead><tr><th>DATASET</th><th>TYPE</th><th>RECORDS</th><th>QUALITY</th><th>VERSION</th><th>CREATED</th><th></th></tr></thead><tbody>{datasets.map(d=><tr key={d.id} onClick={()=>openDataset(d.id)} className="clickable-row"><td><strong>{d.name}</strong></td><td>{titleCase(d.kind)}</td><td>{formatNumber(d.rows)}</td><td><Pill tone={d.score>=90?'good':'warn'}>{d.score}/100</Pill></td><td>v{d.version}</td><td>{d.created_at.slice(0,10)}</td><td><ArrowRight size={16}/></td></tr>)}</tbody></table></div>:<Empty title="No datasets yet" detail="Create your first synthetic dataset to populate this library." action={<button className="button primary" onClick={()=>go('Create Dataset')}>Create dataset</button>}/>}</div></>}

        {screen==='Dataset Preview'&&<><SectionHeading eyebrow="DATASET / PREVIEW" title={result?.name||'Dataset preview'} description={result?`${titleCase(result.kind)} · ${formatNumber(result.quality.counts.rows)} records · v${result.version}`:'Generate or open a dataset to inspect its rows.'} action={result&&<div className="preview-heading-actions"><Pill tone="good"><CheckCircle2 size={14}/> VALIDATED</Pill><button className="button secondary" onClick={()=>{setVersionTarget(result.id);go('Configure Dataset')}}><Plus size={15}/> New version</button></div>}/>{result?<><ActionBar generate={generate} preview={()=>go('Dataset Preview')} validate={()=>go('DataLens')} download={()=>download('csv')} exportPage={()=>go('Export Center')} ready busy={busy}/><div className="preview-tabs">{['Preview','Analytics','Relationships','Quality'].map(tab=><button key={tab} className={previewTab===tab?'active':''} onClick={()=>{setPreviewTab(tab);if(tab==='Analytics')go('DataLens');if(tab==='Relationships')go('Relationships');if(tab==='Quality')go('DataLens')}}>{tab}</button>)}</div><div className="panel table-panel"><div className="table-toolbar"><div className="table-switch">{Object.entries(result.tables).map(([name,table])=><button key={name} className={activeTable===name?'active':''} onClick={()=>{setActiveTable(name);setPage(0);setSearch('')}}>{titleCase(name)} <span>{formatNumber(table.count)}</span></button>)}</div><div className="table-controls"><label className="search-field"><Search size={16}/><input value={search} onChange={e=>{setSearch(e.target.value);setPage(0)}} placeholder="Search rows"/></label><button className="icon-button" title="Filters" onClick={()=>notify('Search filters the current table')}><Filter size={17}/></button><button className="icon-button" title="Columns" onClick={()=>notify('All columns are visible')}><Columns3 size={17}/></button></div></div><div className="table-scroll"><table className="data-table preview-table"><thead><tr><th className="row-number">#</th>{(result.tables[activeTable]?.columns||[]).map(col=><th key={col}>{col.replaceAll('_',' ').toUpperCase()}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}><td className="row-number mono">{page*25+i+1}</td>{(result.tables[activeTable]?.columns||[]).map(col=><td key={col} className={row[col]===null?'missing-cell':rowFlags[i]?.includes('outlier')&&typeof row[col]==='number'?'outlier-cell':rowFlags[i]?.includes('duplicate')?'duplicate-cell':''}>{row[col]===null?<span className="missing-label">missing</span>:numberValue(row[col])}</td>)}</tr>)}</tbody></table></div><div className="table-footer"><span>Showing {rowTotal?formatNumber(page*25+1):0}–{formatNumber(Math.min((page+1)*25,rowTotal))} of {formatNumber(rowTotal)} rows</span><div><button className="button subtle" disabled={page===0} onClick={()=>setPage(page-1)}><ArrowLeft size={15}/> Previous</button><span>Page {page+1}</span><button className="button subtle" disabled={(page+1)*25>=rowTotal} onClick={()=>setPage(page+1)}>Next <ArrowRight size={15}/></button></div></div></div><div className="legend"><span><i className="missing-swatch"/> Missing value</span><span><i className="outlier-swatch"/> Injected outlier</span><span><i className="duplicate-swatch"/> Duplicate values</span><span><ShieldCheck size={15}/> Server-paginated preview</span></div><VersionTimeline versions={versions} current={result.version} open={v=>openDataset(result.id,v)}/></>:<Empty title="Nothing to preview yet" detail="Generate a dataset or open one from the library." action={<button className="button primary" onClick={()=>go('Create Dataset')}>Create dataset</button>}/>}</>}

        {screen==='DataLens'&&<><SectionHeading eyebrow="INSIGHTS / DATALENS" title="DataLens analytics" description="Computed quality, distributions and rule results for the active dataset." action={result&&<Pill tone="accent">{result.name}</Pill>}/>{result?<><div className="datalens-top"><div className="panel health-panel"><div className="eyebrow">DATA HEALTH SCORE</div><div className="health-hero"><strong>{result.quality.score}<small>/100</small></strong><div><h3>{result.quality.score>=90?'Excellent data health':result.quality.score>=75?'Good data health':'Review suggested'}</h3><p>Based on available measured quality dimensions.</p></div></div><ProgressBar value={result.quality.score}/><div className="health-rows">{Object.entries(result.quality.dimensions).map(([name,value])=><div className="health-row" key={name}><span>{name}</span><div className="health-mini"><ProgressBar value={value??0}/></div><strong>{value===null?'N/A':String(value)+'%'}</strong></div>)}</div></div><div className="datalens-side"><div className="panel"><div className="panel-head"><div><h3>Edge-case analysis</h3><p>Injected conditions in this version</p></div><FlaskConical size={19}/></div>{[['Missing values',result.quality.counts.missing,'missing'],['Outliers',result.quality.counts.outliers,'outlier'],['Duplicates',result.quality.counts.duplicates,'duplicate']].map(([label,count,tone])=><div className="edge-row" key={label}><div><span>{label}</span><strong>{formatNumber(count as number)}</strong></div><div className="edge-track"><div className={tone as string} style={{width:`${Math.max(3,Math.min(100,100*(count as number)/Math.max(1,config.rows)*10))}%`}}/></div></div>)}</div><div className="panel privacy-panel"><div className="panel-head"><div><h3>Privacy coverage</h3><p>Sensitive fields and treatments</p></div><ShieldCheck size={19}/></div><div className="privacy-score"><strong>{result.privacy.coverage}%</strong><Pill tone={result.privacy.blocked?'warn':'good'}>{result.privacy.blocked?'EXPORT BLOCKED':'LOW RISK'}</Pill></div><ProgressBar value={result.privacy.coverage}/><div className="privacy-fields">{result.privacy.fields.length?result.privacy.fields.map(f=><div key={f.field}><span>{f.field}</span><Pill tone={f.covered?'good':'warn'}>{f.treatment}</Pill></div>):<span>No sensitive fields detected</span>}</div></div></div></div><ComparisonPanel rows={result.quality.comparison||[]}/><div className="panel rule-panel"><div className="panel-head"><div><h3>Validation checks</h3><p>Integrity and business rules, recomputed from generated rows</p></div><Pill tone="good">{result.quality.checks.filter(c=>c.passed).length}/{result.quality.checks.length} PASSED</Pill></div>{result.quality.checks.length?<div className="check-list">{result.quality.checks.map((c,i)=><div key={i}><span className={c.passed?'pass-icon':'fail-icon'}>{c.passed?<Check size={16}/>:<X size={16}/>}</span><strong>{c.name}</strong><span>{c.detail}</span><Pill tone={c.passed?'good':'warn'}>{c.passed?'PASS':'FAIL'}</Pill></div>)}</div>:<div className="info-strip"><CheckCircle2 size={17}/><div><strong>No rule violations</strong><span>Add numeric business rules in Configure to see per-rule results here.</span></div></div>}</div></>:<Empty icon={BarChart3} title="No analytics yet" detail="Generate a dataset to see computed quality and privacy metrics." action={<button className="button primary" onClick={()=>go('Create Dataset')}>Create dataset</button>}/>}</>}

        {screen==='Relationships'&&<><SectionHeading eyebrow="DATASET / RELATIONSHIPS" title="Relationship map" description="Trace primary and foreign keys through the generated tables."/>{result?.kind==='relational'?<><RelationshipGraph domain={result.config?.domain||'ecommerce'} tables={result.tables}/><div className="info-strip success"><ShieldCheck size={19}/><div><strong>Referential integrity: {result.quality.dimensions['Referential integrity']}%</strong><span>Foreign-key checks are recomputed from this dataset version.</span></div></div></>:<Empty icon={GitBranch} title="Generate a relational dataset" detail="Choose one of the relational domains to see connected tables and validated foreign keys." action={<button className="button primary" onClick={()=>{setConfig({...config,kind:'relational'});go('Configure Dataset')}}>Configure relational data</button>}/>}</>}

        {screen==='Scenarios'&&<><SectionHeading eyebrow="EDGE-CASE LAB" title="Scenario Generator" description="Apply a controlled test condition to your next generation run."/><div className="scenario-grid">{scenarioData.map(s=><div className={'scenario-card '+(config.scenario===s.name?'selected':'')} key={s.name}><div className="scenario-top"><div className="scenario-icon"><s.icon size={21}/></div><span>{s.tag}</span></div><h3>{s.name}</h3><p>{s.description}</p><div className="scenario-rates"><span>Nulls {Math.round(s.values[0]*100)}%</span><span>Outliers {Math.round(s.values[1]*100)}%</span><span>Duplicates {Math.round(s.values[2]*100)}%</span></div><button className="button subtle" onClick={()=>applyScenario(s.name)}>{config.scenario===s.name?'Applied':'Apply scenario'} <ArrowRight size={15}/></button></div>)}</div></>}

        {screen==='Documents'&&<><SectionHeading eyebrow="DOCUMENT ENGINE" title="Business documents" description="Views derived from the same relational rows, with totals computed from line items."/>{result?.kind==='relational'&&['ecommerce','banking'].includes(result.config?.domain||'ecommerce')?<><div className="document-controls"><button className={documentKind==='invoice'?'active':''} disabled={result.config?.domain==='banking'} onClick={()=>setDocumentKind('invoice')}><FileText size={17}/> Invoice</button><button className={documentKind==='statement'?'active':''} disabled={result.config?.domain!=='banking'} onClick={()=>setDocumentKind('statement')}><CreditCard size={17}/> Bank statement</button><Pill tone="accent">SOURCE: {result.name}</Pill></div>{document&&<><div className="document-paper"><div className="document-brand"><Brand/><span>SYNTHETIC DOCUMENT</span></div>{documentKind==='invoice'?<><div className="document-header"><div><span>{document.template?.title||'INVOICE'}</span><h2>#{document.number}</h2></div><div><small>ISSUED</small><strong>{document.date}</strong></div></div><div className="document-parties"><div><small>BILLED TO</small><strong>{document.customer}</strong></div><div><small>FROM</small><strong>Hypersion Demo Co.</strong></div></div><table className="document-table"><thead><tr><th>ITEM</th><th>QTY</th><th>UNIT PRICE</th><th>AMOUNT</th></tr></thead><tbody>{document.items.map((item:any)=><tr key={item.item_id}><td>{item.item}</td><td>{item.qty}</td><td>{formatNumber(item.unit_price)}</td><td>{formatNumber(item.line_total)}</td></tr>)}</tbody></table><div className="document-total"><span>Total</span><strong>{document.currency} {formatNumber(document.total)}</strong></div></>:<><div className="document-header"><div><span>{document.template?.title||'BANK STATEMENT'}</span><h2>Account {document.account}</h2></div><div><small>OPENING BALANCE</small><strong>{document.currency} {formatNumber(document.opening_balance)}</strong></div></div><table className="document-table"><thead><tr><th>DATE</th><th>DESCRIPTION</th><th>DEBIT</th><th>CREDIT</th><th>BALANCE</th></tr></thead><tbody>{document.transactions.map((t:any,i:number)=><tr key={i}><td>{t.date}</td><td>{t.description}</td><td>{formatNumber(t.debit)}</td><td>{formatNumber(t.credit)}</td><td>{formatNumber(t.balance)}</td></tr>)}</tbody></table><div className="document-total"><span>Closing balance</span><strong>{document.currency} {formatNumber(document.closing_balance)}</strong></div></>}</div><div className="download-actions document-downloads">{['pdf','json','csv','txt'].map(fmt=><button key={fmt} className="button secondary" onClick={()=>downloadDocument(fmt)} disabled={result.privacy.blocked}><Download size={16}/> Download {fmt.toUpperCase()}</button>)}</div></>}</>:<Empty icon={FileText} title="Documents need relational rows" detail="Generate e-commerce data for invoices or banking data for statements." action={<button className="button primary" onClick={()=>{setConfig({...config,kind:'relational'});go('Configure Dataset')}}>Configure relational data</button>}/>}</>}

        {screen==='Export Center'&&<><SectionHeading eyebrow="OUTPUT / EXPORTS" title="Export Center" description="Get server-generated files for development, testing and review."/>{result?<><div className="export-summary"><div><FileArchive size={22}/><div><strong>{result.name}</strong><span>v{result.version} · {formatNumber(result.quality.counts.rows)} total rows · {Object.keys(result.tables).length} table(s)</span></div></div><Pill tone={result.privacy.blocked?'warn':'good'}>{result.privacy.blocked?'PRIVACY BLOCK':'READY TO EXPORT'}</Pill></div>{result.privacy.blocked&&<div className="info-strip warning"><ShieldCheck size={19}/><div><strong>Export blocked by privacy scan</strong><span>Set a treatment on every sensitive field in the schema, then regenerate.</span></div></div>}<div className="export-grid">{[{fmt:'csv',name:'CSV tables',icon:FileSpreadsheet,detail:'Spreadsheet and ETL ready'},{fmt:'json',name:'Structured JSON',icon:FileJson,detail:'Nested tables for APIs'},{fmt:'txt',name:'Plain text',icon:FileText,detail:'Readable record output'},{fmt:'pdf',name:'PDF report',icon:FileText,detail:'Quality and sample report'},{fmt:'sql',name:'SQL script',icon:Database,detail:'Create and insert statements'},{fmt:'zip',name:'Complete package',icon:FileArchive,detail:'All tables and metadata'}].map(x=><div className="export-card" key={x.fmt}><div className="export-icon"><x.icon size={22}/></div><h3>{x.name}</h3><p>{x.detail}</p><button className="button secondary" disabled={result.privacy.blocked} onClick={()=>download(x.fmt)}><Download size={16}/> Download {x.fmt.toUpperCase()}</button></div>)}</div><div className="panel package-panel"><div className="panel-head"><div><h3>Package contents</h3><p>ZIP includes every table and run metadata</p></div><FileArchive size={19}/></div><div className="file-tree"><div><FileArchive size={16}/> hypersion_dataset/</div>{Object.keys(result.tables).map(x=><div key={x}><FileSpreadsheet size={15}/> {x}.csv</div>)}<div><FileJson size={15}/> metadata.json</div><div><FileText size={15}/> README.txt</div></div></div></>:<Empty icon={Download} title="Nothing to export yet" detail="Generate a dataset, then download it in the format your workflow needs." action={<button className="button primary" onClick={()=>go('Create Dataset')}>Create dataset</button>}/>}</>}

        {screen==='Templates'&&<><SectionHeading eyebrow="QUICK START" title="Templates" description="Start from a known structure, then edit it to fit your use case."/><div className="template-grid">{[{name:'Customer profiles',kind:'tabular',icon:Database,desc:'People, contact details, geography and balances.'},{name:'E-commerce operations',kind:'relational',icon:GitBranch,desc:'Customers, products, orders, items and payments.'},{name:'Banking accounts',kind:'banking',icon:CreditCard,desc:'Customers, accounts and running-balance transactions.'},{name:'Financial transactions',kind:'transaction',icon:CreditCard,desc:'Amounts, merchants and transaction dates.'},...['hospital','university','inventory','hr','hotel','library'].map(domain=>({name:titleCase(domain)+' operations',kind:domain,icon:GitBranch,desc:'Connected '+titleCase(domain).toLowerCase()+' tables with validated keys.'}))].map(t=><div className="template-card" key={t.name}><div className="template-icon"><t.icon size={26}/></div><Pill tone="accent">{t.kind==='relational'||t.kind==='banking'||relationalSchemas[t.kind]?'RELATIONAL':'TABULAR'}</Pill><h3>{t.name}</h3><p>{t.desc}</p><button className="button secondary" onClick={()=>t.kind==='transaction'?(setPrompt('Generate 10,000 financial transactions with amounts, merchants and dates'),go('Create Dataset')):selectTemplate(t.kind)}>Use template <ArrowRight size={16}/></button></div>)}</div></>}

        {screen==='Usage & Settings'&&<><SectionHeading eyebrow="WORKSPACE" title="Usage & settings" description="Monitor local generation activity and choose your workspace appearance."/><div className="metrics-grid"><Metric label="Generated rows" value={formatNumber(datasets.reduce((a,d)=>a+d.rows,0))} detail="Across your workspace" icon={Table2}/><Metric label="Datasets" value={datasets.length} detail="Saved in the workspace database" icon={Database}/><Metric label="AI model calls" value="—" detail="OpenRouter usage unavailable locally" icon={Sparkles}/><Metric label="Credits" value={billing?formatNumber(billing.balance):'—'} detail={billing?'Available for generation':'Loading account balance'} icon={CreditCard}/></div><div className="settings-grid"><div className="panel"><div className="panel-head"><div><h3>Appearance</h3><p>Set the workspace theme</p></div><Settings2 size={19}/></div><div className="theme-options"><button className={theme==='dark'?'active':''} onClick={()=>setTheme('dark')}>Dark workspace</button><button className={theme==='light'?'active':''} onClick={()=>setTheme('light')}>Light workspace</button></div></div><div className="panel"><div className="panel-head"><div><h3>Local environment</h3><p>Current backend capabilities</p></div><LockKeyhole size={19}/></div><div className="summary-list"><div><span>Persistence</span><strong>{databaseStatus?.provider==='supabase-postgres'?'Supabase Postgres':databaseStatus?.provider==='postgres'?'Postgres':databaseStatus?.provider==='sqlite'?'SQLite local':'Unavailable'}</strong></div><div><span>Browser client</span><strong>{supabase?'Configured':'Not configured'}</strong></div><div><span>Generation</span><strong>NumPy + SciPy</strong></div><div><span>AI gateway</span><strong>Server-side OpenRouter</strong></div><div><span>Authentication</span><strong>{supabase?'Email link':'Not configured'}</strong></div></div></div></div></>}

        {screen==='API Playground'&&<><SectionHeading eyebrow="DEVELOPER" title="API Playground" description="Exercise generation, dataset and export endpoints on your local API."/><div className="api-layout"><div className="panel"><div className="panel-head"><div><h3>Request</h3><p>Protected backend API</p></div><Pill tone="accent">API</Pill></div><div className="form-grid"><label>Method<select value={apiMethod} onChange={e=>setApiMethod(e.target.value as 'GET'|'POST')}><option>GET</option><option>POST</option></select></label><label>Endpoint<select value={apiEndpoint} onChange={e=>{const endpoint=e.target.value;const post=endpoint==='/api/generate'||endpoint==='/api/analyze/prompt';setApiEndpoint(endpoint);setApiMethod(post?'POST':'GET');if(post)setApiBody(JSON.stringify(endpoint==='/api/analyze/prompt'?{prompt}:config,null,2))}}><option value="/api/health">GET /api/health</option><option value="/api/integrations">GET /api/integrations</option><option value="/api/datasets">GET /api/datasets</option><option value="/api/analyze/prompt">POST /api/analyze/prompt</option><option value="/api/generate">POST /api/generate</option>{result&&<><option value={`/api/datasets/${result.id}`}>GET /api/datasets/{'{id}'}</option><option value={`/api/datasets/${result.id}/rows?table=${encodeURIComponent(activeTable)}&limit=25`}>GET /api/datasets/{'{id}'}/rows</option><option value={`/api/datasets/${result.id}/export/csv?version=${result.version}`}>GET /api/datasets/{'{id}'}/export/csv</option></>}</select></label></div>{apiMethod==='POST'&&<label className="field-label">JSON REQUEST BODY<textarea className="api-request-body" value={apiBody} onChange={e=>setApiBody(e.target.value)} spellCheck={false}/></label>}<button className="button primary" disabled={apiBusy} onClick={sendApiRequest}><Play size={16}/>{apiBusy?'Sending…':'Send request'}</button><div className="api-hint"><KeyRound size={16}/><span>JSON content type is sent for POST. Your Supabase session is sent with protected API requests.</span></div></div><div className="panel"><div className="panel-head"><div><h3>Response</h3><p>{apiStatus===null?'JSON response viewer':`HTTP ${apiStatus} · ${apiStatus>=200&&apiStatus<300?'Success':'Request failed'}`}</p></div><div className="api-response-actions"><button className="icon-button" title="Copy response" disabled={!apiResponse} onClick={()=>navigator.clipboard.writeText(apiResponse).then(()=>notify('Response copied')).catch(()=>notify('Clipboard access is unavailable'))}><Copy size={16}/></button><button className="icon-button" title="Download response" disabled={!apiResponse} onClick={downloadApiResponse}><Download size={16}/></button></div></div><pre className="api-response">{apiResponse||'{\n  "message": "Send a request to inspect the response"\n}'}</pre></div></div></>}

        {screen==='Help'&&<><SectionHeading eyebrow="SUPPORT" title="Help & documentation" description="The shortest path from an idea to a usable dataset."/><div className="help-grid">{[{step:'01',title:'Describe or upload',body:'Write your data need in plain language, or upload a small UTF-8 CSV sample.'},{step:'02',title:'Review the schema',body:'Adjust types, keys and privacy rules. AI and inference make proposals you can edit.'},{step:'03',title:'Set generation rules',body:'Choose volume, seed, locale and edge-case rates. A fixed seed keeps runs reproducible.'},{step:'04',title:'Validate and export',body:'Inspect the paginated table, quality score, privacy coverage and server-generated files.'}].map(h=><div className="help-card" key={h.step}><span>{h.step}</span><h3>{h.title}</h3><p>{h.body}</p></div>)}</div><div className="info-strip"><BookOpen size={19}/><div><strong>Developer API</strong><span>Full endpoint schemas and interactive testing are available at localhost:8000/docs when the backend is running.</span></div></div></>}
        {screen==='Usage & Settings'&&<BillingPlans billing={billing}/>}
      </main>
    </div>
    <input ref={fileRef} type="file" accept=".csv,text/csv" hidden onChange={e=>{const file=e.target.files?.[0];if(file)upload(file);e.target.value=''}}/>
    {toast&&<div className="toast"><CheckCircle2 size={17}/>{toast}<button onClick={()=>setToast('')} aria-label="Dismiss"><X size={15}/></button></div>}
  </div>
}

function BillingPlans({billing}:{billing:Billing|null}){
  return <section className="billing-plans"><SectionHeading eyebrow="CREDITS / EASYPaisa" title="Credits and paid plans" description={billing?`${formatNumber(billing.balance)} credits available · ${billing.credits_per_thousand_rows} credit per 1,000 generated rows`:'Loading account credits'} action={<Pill tone={billing?.checkout_ready?'good':'warn'}>{billing?.checkout_ready?'EASYPAISA READY':'EASYPAISA SETUP REQUIRED'}</Pill>}/><div className="billing-plan-grid">{billing?.plans.map(plan=><article className="billing-plan" key={plan.id}><div className="billing-plan-heading"><span>{plan.name}</span><strong>PKR {formatNumber(plan.price_pkr)}</strong></div><p><strong>{formatNumber(plan.credits)} credits</strong><span>Credit package</span></p><button className="button secondary" disabled={!billing.checkout_ready}>Easypaisa checkout unavailable</button></article>)}</div><p className="billing-note">Purchases stay disabled until the official Easypaisa merchant flow is connected and verified.</p></section>
}

function AuthScreen({configured,loading,busy,error,notice,onSignIn}:{configured:boolean;loading:boolean;busy:boolean;error:string;notice:string;onSignIn:(email:string)=>Promise<void>}){
  const [email,setEmail]=useState('')
  return <main className="auth-screen"><section className="auth-panel" aria-labelledby="auth-title"><Brand/><div className="auth-copy"><span>HYPERSION WORKSPACE</span><h1 id="auth-title">Sign in to continue</h1><p>Enter your email and we’ll send you a secure sign-in link.</p></div><form onSubmit={event=>{event.preventDefault();void onSignIn(email.trim())}}><label className="auth-label" htmlFor="auth-email">Email address</label><input id="auth-email" className="auth-input" type="email" autoComplete="email" required value={email} onChange={event=>setEmail(event.target.value)}/><button className="auth-submit" type="submit" disabled={!configured||loading||busy}>{loading?'Checking session…':busy?'Sending link…':'Email me a sign-in link'}</button></form>{!configured&&<p className="auth-message" role="alert">Supabase is not configured. Set the VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY environment variables.</p>}{error&&<p className="auth-message" role="alert">{error}</p>}{notice&&<p className="auth-message success" role="status">{notice}</p>}<p className="auth-foot">Protected by Supabase authentication</p></section></main>
}

function ValidationExplanation({datasetId,version}:{datasetId:string;version:number}){
  const [busy,setBusy]=useState(false)
  const [error,setError]=useState('')
  const [explanation,setExplanation]=useState<{summary:string;priorities:string[]}|null>(null)
  useEffect(()=>{setError('');setExplanation(null)},[datasetId,version])
  async function explain(){
    setBusy(true);setError('')
    try{setExplanation(await request(`/datasets/${datasetId}/explain-validation?version=${version}`,{method:'POST'}))}
    catch(e){setError((e as Error).message)}
    finally{setBusy(false)}
  }
  return <div className="panel validation-explanation"><div className="panel-head"><div><h3>AI validation explanation</h3><p>Explains computed metrics only; dataset rows are never sent.</p></div><button className="button secondary" disabled={busy} onClick={explain}><Sparkles size={16}/>{busy?'Explaining…':'Explain results'}</button></div>{error&&<div className="info-strip warning"><span>{error}</span></div>}{explanation&&<><p>{explanation.summary}</p>{explanation.priorities.length>0&&<div className="summary-list">{explanation.priorities.map((priority,index)=><div key={index}><span>Priority {index+1}</span><strong>{priority}</strong></div>)}</div>}</>}</div>
}

function FlowHeader({step,title,subtitle}:{step:number;title:string;subtitle:string}){return <><div className="flow-track">{['Input','Understand','Configure','Generate','Validate','Visualize','Export'].map((name,i)=><div key={name} className={i<step?'active':''}><span>{String(i+1).padStart(2,'0')}</span>{name}{i<6&&<ArrowRight size={14}/>}</div>)}</div><SectionHeading eyebrow={`${String(step).padStart(2,'0')} / GENERATION STUDIO`} title={title} description={subtitle}/></>}
function ActionBar({generate,preview,validate,download,exportPage,ready,busy}:{generate:()=>void;preview:()=>void;validate:()=>void;download:()=>void;exportPage:()=>void;ready:boolean;busy:boolean}){return <div className="action-bar"><span>DATASET ACTIONS</span><button onClick={generate} disabled={busy}><Play size={15}/> Generate</button><button onClick={preview} disabled={!ready}><Table2 size={15}/> Preview</button><button onClick={validate} disabled={!ready}><ShieldCheck size={15}/> Validate</button><button onClick={download} disabled={!ready}><Download size={15}/> Download</button><button onClick={exportPage} disabled={!ready}><ArrowDownToLine size={15}/> Export</button></div>}
function ComparisonPanel({rows}:{rows:{field:string;measure:string;sample:number;synthetic:number;similarity:number}[]}){return <div className="panel comparison-panel"><div className="panel-head"><div><h3>Sample vs synthetic</h3><p>Measured from the uploaded sample and generated values</p></div><Pill tone="accent">DISTRIBUTION FIDELITY</Pill></div>{rows.length?<div className="comparison-list">{rows.map(row=><div className="comparison-row" key={row.field}><div className="comparison-meta"><strong>{titleCase(row.field)}</strong><span>{row.measure} · {row.similarity}% similar</span></div><div className="comparison-bars"><div><span>Sample</span><div className="comparison-track"><i style={{width:`${Math.max(3,100*row.sample/Math.max(row.sample,row.synthetic,1))}%`}}/></div><b>{numberValue(row.sample)}</b></div><div><span>Synthetic</span><div className="comparison-track synthetic"><i style={{width:`${Math.max(3,100*row.synthetic/Math.max(row.sample,row.synthetic,1))}%`}}/></div><b>{numberValue(row.synthetic)}</b></div></div></div>)}</div>:<div className="comparison-empty">Upload a CSV sample to compare its numeric means and category distributions with the synthetic output. Statistical similarity is excluded from the score until a sample is available.</div>}</div>}
function VersionTimeline({versions,current,open}:{versions:VersionSummary[];current:number;open:(version:number)=>void}){return <div className="panel version-panel"><div className="panel-head"><div><h3>Version history</h3><p>Each version stores its schema, settings, seed and validation report</p></div><GitBranch size={19}/></div><div className="version-list">{versions.map(v=><button key={v.version} className={v.version===current?'active':''} onClick={()=>open(v.version)}><span className="version-node">v{v.version}</span><div><strong>{formatNumber(v.config.rows)} rows · {v.config.scenario}</strong><small>Seed {v.config.seed} · {v.created_at.slice(0,16)}</small></div><Pill tone={v.score>=90?'good':'warn'}>{v.score}/100</Pill>{v.version===current&&<span className="version-current">VIEWING</span>}</button>)}</div></div>}
function RelationalSchema({domain}:{domain:string}){const tables=relationalSchemas[domain]||relationalSchemas.ecommerce;return <div className="panel relational-schema"><div className="panel-head"><div><h3>Built-in {titleCase(domain)} relationships</h3><p>Keys and totals are managed by the relational engine.</p></div><Pill tone="accent">{tables.length} TABLES</Pill></div><div className="relational-schema-grid">{tables.map(([name,...fields])=><div key={name}><div><Database size={16}/><strong>{titleCase(name)}</strong></div>{fields.map(field=><span key={field}>{field.replace(/ (PK|FK)$/,'')} {field.endsWith(' PK')?<Pill tone="accent">PK</Pill>:field.endsWith(' FK')?<Pill>FK</Pill>:null}</span>)}</div>)}</div><div className="relational-schema-note">Choose the relational domain and generation rules in Configure. Custom relational schema editing is not part of this local engine.</div></div>}

function RelationshipGraph({domain,tables}:{domain:string;tables:Record<string,TableData>}){
  const schema=relationalSchemas[domain]||relationalSchemas.ecommerce
  const edges=relationEdges[domain]||relationEdges.ecommerce
  return <div className="panel relationship-panel"><div className="panel-head"><div><h3>{titleCase(domain)} schema</h3><p>{schema.length} tables · {edges.length} foreign-key relationships</p></div><GitBranch size={19}/></div><div className="relationship-tables">{schema.map(([name,...fields])=><div className="relationship-table" key={name}><div><Database size={16}/><strong>{titleCase(name)}</strong><span>{formatNumber(tables[name]?.count||0)} rows</span></div>{fields.map(field=><div key={field}><span>{field.replace(/ (PK|FK)$/,'')}</span>{field.endsWith(' PK')?<Pill tone="accent">PK</Pill>:field.endsWith(' FK')?<Pill>FK</Pill>:null}</div>)}</div>)}</div><div className="relationship-links"><h4>Key connections</h4>{edges.map(([parent,child,key])=><div key={`${parent}-${child}-${key}`}><strong>{titleCase(parent)}</strong><ArrowRight size={15}/><strong>{titleCase(child)}</strong><span>{key} · one to many</span></div>)}</div></div>
}










